        wr_vec(w, "particle_info", &self.particle_info, self.vertices.ev(), 0)?;
        wr(w, "has_rotation_speeds", &self.has_rotation_speeds, 0)?;
        if (self.has_rotation_speeds.ev() != 0) {
            wr_vec(w, "rotation_speeds", &self.rotation_speeds, self.vertices.ev(), 0)?;
        }
        wr(w, "num_added_particles", &self.num_added_particles, 0)?;
        wr(w, "added_particles_base", &self.added_particles_base, 0)?;
        Ok(())
