        out.push(field(&FI_NI_P_SYS_DATA_ROTATION_SPEEDS, (self.has_rotation_speeds.ev() != 0), self.rotation_speeds.as_value(0)));
        out.push(field(&FI_NI_P_SYS_DATA_NUM_ADDED_PARTICLES, true, self.num_added_particles.as_value(0)));
